# S104 round 2 (maths): the inventions register, as data.
# Each entry: id, title, quotes [(line, exact text)], invented, others (the other choices that were
# possible), core (sections of "formal core.md" that use it). The claims that depend on each
# invention are read from s104_claims.py by the builder, so the two lists cannot drift apart.
# Nothing here is the text's own content: each entry is a choice the text leaves open.

INVENTIONS = [
dict(id="I01", title="Composition of edits: a partial monoid with Kleene associativity",
 quotes=[(91, r'''\(A\) is a set of admitted edits, closed under a partial associative composition with identity \(1\).''')],
 invented="(A, ·, 1) is a partial binary operation on A: a2·a1 is either undefined or a member of A; a3·(a2·a1) is defined exactly when (a3·a2)·a1 is, and then they are equal; 1·a = a·1 = a for every a. 'Closed' is read as: a composite, when defined, is in A.",
 others=["weak associativity: equal only when both sides happen to be defined",
         "a category: edits typed by source and target boundary, composable only when they match",
         "a total monoid (every composite defined)"],
 core=["§1"]),

dict(id="I02", title="No law links a composite edit's relations to its parts' relations",
 quotes=[(91, r'''For each \(j\), edit \(a\), and boundary \(b\), the interpretation supplies'''),
         (574, r'''The component relations \(L_j(a,b)\) are supplied independently for each \((a,b)\).''')],
 invented="L is an arbitrary function J × A × B → relations. Nothing ties L_j(a2·a1, b) to L_j(a1, b) and L_j(a2, b). The composition on A matters only through the homomorphism clause of (F2) and through Functional transport. (L574 fixes independence across pairs; it does not say whether composites are constrained, so the absence of any such law is the invention.)",
 others=["an action law: each edit acts on the assignment of relations, L(a2·a1) = a2·(a1·L)",
         "edits as endomaps of the organization, with L read off the image"],
 core=["§1", "§12"]),

dict(id="I03", title="Ports and components are fixed; deletion and absence are the full relation",
 quotes=[(103, r'''A deleted component imposes the full relation on its ports.'''),
         (339, r'''has a target \(D\) in which the ports and components a rival account would need are absent''')],
 invented="An edit never adds or removes a member of V or J. A deleted or absent component is one whose relation under that edit and boundary is the full product of its ports' domains. An 'absent' port is one on which every component that could constrain it imposes the full relation.",
 others=["edits that change J and V (organizations as a varying family; then Sol_D(a,b) lives in different spaces for different edits)",
         "absent ports removed from V, with query answers compared across different valuation spaces"],
 core=["§1", "§6", "§7", "§17"]),

dict(id="I04", title="Setting a port: a surgical edit, and the assigning component read off the edits",
 quotes=[(103, r'''An edit that sets a port replaces the component assigning that port; it does not add an equation beside an incompatible one.'''),
         (109, r'''No role assignment is supplied. A port \(v\) is an **input** under \(A\) when \(A\) contains an edit that sets \(v\) directly.'''),
         (119, r'''An edit that sets a port replaces only the component that assigns the port (above), not the relations of the components that read it''')],
 invented="An edit a sets port v at boundary b through component j when L_j(a,b) = {w : w_v = x} for some x in X_v (the other ports of V_j left free) and L_k(a,b) = L_k(1,b) for every k ≠ j. 'Directly' is this surgical form. The component assigning v, asg(v), is read off A: it is the component that the setting edits of v replace; where two different components are replaced by setting edits of v, asg(v) is undefined. No assignment map is supplied with D.",
 others=["(a) a declared map asg: V ⇀ J supplied with the organization (it would be a supplied role assignment, which L109's first sentence denies)",
         "(b) asg(v) := the unique component of which v is an output in L109's second sense; this fails for relational components (a component L = H cot θ determines H given L and θ as well as L given H and θ)",
         "(c) a setting edit that adds a constraint beside the old one (L103 excludes it)"],
 core=["§2", "§4", "§17"]),

dict(id="I05", title="'Output': at the identity edit, and 'determined' as at most one value",
 quotes=[(109, r'''A port is an **output** of component \(j\) when its value is determined by \(L_j\) given the other ports of \(V_j\) across \(B\).''')],
 invented="v is an output of j when, for every b in B and all w, w' in L_j(1,b), w and w' agreeing off v implies w_v = w'_v. The relation is read at the identity edit; 'determined' means at most one value (a partial function), not exactly one.",
 others=["at every edit of A that does not replace j", "exactly one value for every admissible value of the other ports (a total function)", "'across B' read as 'for some b'"],
 core=["§2"]),

dict(id="I06", title="Observation edits: two readings of 'the relation reporting it'",
 quotes=[(109, r'''A port is an **observation** when \(A\) contains an edit that alters the relation reporting it without altering what it reports, that is, when the component assigning it has a measurement's signature (below).'''),
         (127, r'''In particular, a part that reads or reports another part has a measurement's signature: change only the reading and the part it reports stays as it was; change the part and the reading follows.''')],
 invented="The observed port is the reading o (the port the reporting component assigns), and 'what it reports' is a port m read by that component, compared at the level of relations: the edit leaves L_asg(m) as it was. Two readings of which edits count are both carried, since the text does not decide between them. Reading R-i: any edit that alters asg(o) and leaves asg(m) as it was, including an edit that sets o (the reading the round-1 critical review uses: 'an intervention on the reading is, by L109, an observation edit for the measured port'; it also matches L127's 'a part that reads … another part has a measurement's signature'). Reading R-ii: only an edit that alters asg(o) without setting o (a recalibration of the reporting relation). Where a program has to choose one, it runs both and reports both.",
 others=["'the relation reporting it' read with the port as the thing reported (then the 'that is' clause, which speaks of the component assigning the port, no longer matches)",
         "'what it reports' compared at the level of solutions: the projection of Sol on m unchanged",
         "a declared measured port for each observation (a supplied role, against L109's first sentence)"],
 core=["§2", "§4"]),

dict(id="I07", title="'The measured port' and 'the measuring relation'",
 quotes=[(124, r'''- a **measurement** has a signature invariant under interventions on the measured port and variable under edits to the measuring relation;''')],
 invented="Measurement is a relation between a component j and a port m: m is in V_j and is not assigned by j; 'the measuring relation' is L_j itself; 'edits to the measuring relation' are, under R-i, edits that alter L_j, and under R-ii, edits that alter L_j without setting j's output. A component with several read ports is a measurement of each separately.",
 others=["the measured port declared with the component", "the measuring relation as a separate component reading m"],
 core=["§4"]),

dict(id="I08", title="'Interventions on the world' and 'the rule'",
 quotes=[(125, r'''- a **rule application** has a signature invariant under interventions on the world and variable under edits to the rule.''')],
 invented="'The rule' is the component j itself; 'edits to the rule' are edits that alter L_j without setting j's output; 'interventions on the world' are setting edits of every port that j does not assign.",
 others=["'the world' as the ports j reads only", "'the rule' as a port whose value j reads (a rule carried as data, as the relation C_r of L347 might be read)"],
 core=["§4"]),

dict(id="I09", title="'Changes under', 'invariant under', 'variable under': compared with the identity edit at the same boundary",
 quotes=[(123, r'''- a **causal assignment** has a signature that changes under intervention on its output port and is invariant under observation edits;''')],
 invented="For a class 𝒳 of edits: j's signature changes (is variable) under 𝒳 on C when some (a,b) in C with a in 𝒳 has L_j(a,b) ≠ L_j(1,b); it is invariant under 𝒳 on C when every (a,b) in C with a in 𝒳 has L_j(a,b) = L_j(1,b). The comparison is with the identity edit at the same boundary, whether or not (1,b) is in C. Invariance is met vacuously when C holds no edit of 𝒳.",
 others=["compare with the baseline pair (1,b0) instead of (1,b)", "compare only pairs that are both in C", "'changes under intervention' read universally (every such intervention changes it)"],
 core=["§4"]),

dict(id="I10", title="Kinds: a footprint bijection between equal value domains, relations compared as sets",
 quotes=[(119, r'''Two components \(j,j'\) are **of one kind on \(C\)** when there is a bijection of their footprints under which \(\operatorname{sig}_C(j)\) and \(\operatorname{sig}_C(j')\) coincide.''')],
 invented="j and j' are of one kind on C when some bijection β: V_j → V_j' with X_v = X_β(v) for every v gives L_j'(a,b) = β_*(L_j(a,b)) for every (a,b) in C, where β_* renames coordinates. Values are compared as elements.",
 others=["allow a value bijection for each port as well (kinds up to recoding of values; far coarser)", "require β to be the identity on the ports the two components share"],
 core=["§4", "§5"]),

dict(id="I11", title="'Coarser' and 'finer' contracts: fewer and more pairs",
 quotes=[(119, r'''Kinds are therefore relative to the contract; a coarser contract identifies more components, and two components of one kind on \(C\) may separate on a finer contract.'''),
         (317, r'''A finer contract that contains a change at which two rivals conflict makes a new question (Part III)''')],
 invented="C' is coarser than C when C' ⊆ C, finer when C' ⊇ C (both on the same target, with the same baseline).",
 others=["coarser as the image of C under a quotient of edits or boundaries (a coarser grain)", "coarser as fewer distinguishable pairs, however many pairs it has"],
 core=["§4", "§10"]),

dict(id="I12", title="Reading a candidate's component on C through the transport; τ[C]",
 quotes=[(119, r'''A component of \(E\) and a component of \(E'\) are of one kind on \(C\) when their signatures, read on \(C\) through \(\tau\) and \(\tau'\), coincide under a footprint bijection'''),
         (554, r'''no active component \(k\) of \(E\) has a signature on \(\tau[C]\) that differs from the one its counterpart \(\lambda(k)\) has on \(C\), up to the port translation.''')],
 invented="The signature of k in E read on C through t = (π,τ,σ,λ) is the function on C sending (a,b) to L_k(τ(a),σ(b)); boundaries are translated by σ although L119 names only τ. τ[C] := {(τ(a),σ(b)) : (a,b) in C}. Signatures on C and on τ[C] are compared as functions on C.",
 others=["read through τ only, with E's boundary held at σ(b0)", "τ[C] as a set of edits only", "compare the two signatures as sets of triples, which needs τ×σ injective on C"],
 core=["§4", "§5"]),

dict(id="I13", title="(K) extended from components to subnetworks",
 quotes=[(556, r'''By (K), \(\operatorname{sig}_C(\lambda(k))=\{(a,b,\operatorname{proj}^{\lambda}_{V_k}\operatorname{Sol}_{\lambda(k)}(a,b))\}\)''')],
 invented="(K) is stated for a component. For a subnetwork N of D with a port translation θ into it, sig_C(N,θ) := {(a,b, proj^θ Sol_N(a,b)) : (a,b) in C} is taken as a definition (an extension of (K)), not as something (K) already gives.",
 others=["treat a subnetwork as one composite component whose relation is the projected relation (then (K) applies as written)", "leave Argument 1's 'By (K)' without a definition to rest on"],
 core=["§4", "§5"]),

dict(id="I14", title="Subnetworks, their solutions, and port translations with value maps",
 quotes=[(189, r'''\(\lambda\) assigns each component of \(E\) a subnetwork of \(D\) with a port translation.'''),
         (233, r'''the relation obtained by imposing the constraints of \(\lambda(k)\), projecting away its hidden ports and carrying what remains to \(V_k\) by the port translation of \(\lambda\)''')],
 invented="A subnetwork N is a subset of J_D (possibly empty); V_N is the union of its footprints; Sol_N(a,b) = {z in ∏_{V_N} X_v : z|V_j ∈ L_j(a,b) for every j in N}: the constraints of N alone, the rest of D ignored. A port translation for k is an injective map θ_k: V_k → V_N with a value map κ_v: X^D_θk(v) → X^E_v for each v (the identity where the domains agree). Hidden ports are V_N minus the image of θ_k. proj^λ_Vk(S) = {(κ_v(z_θk(v)))_{v in V_k} : z in S}.",
 others=["Sol of λ(k) in the context of the whole of D (the projection of Sol_D)", "a port translation as a map from V_N to V_k (several D ports to one E port)", "a subnetwork as a set of ports rather than of components"],
 core=["§5"]),

dict(id="I15", title="'Active component' means a member of Γ",
 quotes=[(233, r'''**Component fidelity.** For every active component \(k\) of \(E\) with counterpart subnetwork \(\lambda(k)\subseteq D\)''')],
 invented="The active components of a candidate are exactly its commitments Γ; (F1) is required of these only.",
 others=["every component of E", "every component with a counterpart assigned by λ (L189 has λ assign one to every component)"],
 core=["§5", "§6"]),

dict(id="I16", title="The domain of π: 'on the stated scope'",
 quotes=[(189, r'''where \(\pi:X_D\to X_E\) on the stated scope''')],
 invented="π is a map defined at least on the union of Sol_D(a,b) over the pairs (a,b) the transport translates; elsewhere it may be undefined.",
 others=["π total on X_D", "π a relation (several images per valuation)"],
 core=["§5"]),

dict(id="I17", title="Partial τ and σ; which pairs a transport 'translates'",
 quotes=[(315, r'''they conflict at some admitted edit–boundary pair of the target that both their transports translate, in \(C\) or outside it.''')],
 invented="τ: A_D ⇀ A_E and σ: B_D ⇀ B_E are partial maps; t translates (a,b) when a is in dom τ, b is in dom σ and π is defined on Sol_D(a,b).",
 others=["τ and σ total (then every admitted pair is translated)", "'translate' read as 'is in C'"],
 core=["§5", "§8"]),

dict(id="I18", title="The homomorphism clause of (F2): its range, and that it is not pointwise",
 quotes=[(242, r'''\tau(1)=1,\quad \tau(a_2a_1)=\tau(a_2)\tau(a_1).''')],
 invented="τ(1) = 1, and for all a1, a2 in dom τ with a2·a1 defined in A_D, τ(a2)·τ(a1) is defined in A_E and equals τ(a2·a1). The clause is a condition on τ as a whole, not at a pair; '(F2) at a pair' means only the valuation equation there.",
 others=["only for edits occurring in C, and composites that are in C", "only when both composites are defined", "the clause counted at each pair (then (F2) at a pair depends on edits outside it)"],
 core=["§5", "§8"]),

dict(id="I19", title="Meeting (F1), (F2) and (A) at one pair under hypothetical relations of the target",
 quotes=[(315, r'''when their answers there differ, or when each of them could meet (F1), (F2) and (A) there under some relations of the target's components at that pair, each a relation on the component's footprint (Part II), and no such relations let both''')],
 invented="For a pair (a,b) and an assignment R = (R_j)_{j in J_D}, R_j ⊆ ∏_{V_j} X_v: D^R is D with its relations at (a,b) replaced by R; Meets_ab(ℰ,R) is (F1) at (a,b) for every k in Γ with Sol_λ(k) computed from R, the valuation equation of (F2) with Sol_D^R, and (A) with the target's answer computed by the query on D^R. The homomorphism clause is left out at a pair (I18). R ranges over every assignment of relations on the footprints.",
 others=["include the homomorphism clause", "R ranging only over assignments some physics admits (L315 excludes it: 'it does not turn on what any physics admits')", "R ranging over the relations the target has at other admitted pairs"],
 core=["§8", "§10"]),

dict(id="I20", title="How the fixed query is applied to a candidate's organization",
 quotes=[(141, r'''\(\mathcal Q\) is a specified set-theoretic operation on \(D\), its solutions and its component structure, with codomain \(Y_p\).'''),
         (253, r'''The query \(\mathcal Q\) is held fixed; an account of a different query is not an account of this one.''')],
 invented="Q is an operation on any evaluated organization (O, a, b), taking Sol_O(a,b), the relations (L_j(a,b))_j and a designation δ_O of the ports and components it reads; its values lie in Y_p. For the target, δ_D is part of the question. For a candidate, δ_E is supplied with the transport: by default, the ports of E whose translations are the ports Q reads in D. Ans_E(a',b') := Q(E, a', b'; δ_E).",
 others=["(a) Ans_E supplied as part of the candidate (then 'held fixed' constrains only a label)", "(b) a shared space of port names, Q reading by name", "(c) Ans_E computed from the π-preimage of Sol_E"],
 core=["§3", "§5", "§6"]),

dict(id="I21", title="Undetermined answers: a value ⊥",
 quotes=[(255, r'''the answers of \(E\) with \(G\) deleted are determined and equal, or an answer that \(E\) determines at one of these points is not determined there once \(G\) is deleted.''')],
 invented="Q returns an element of Y_p or ⊥ ('not determined'); for a query reading a port, the answer is determined when the port's projection of Sol is a single value, and is ⊥ when it is empty or has several. Two ⊥ answers count as equal where answers are compared (conflict, (A)).",
 others=["Q returns the set of possible values, 'determined' meaning a singleton", "⊥ split into 'none' and 'several'", "two ⊥ answers counted as different"],
 core=["§3", "§6", "§8"]),

dict(id="I22", title="'Not determined … in the claimed way'",
 quotes=[(255, r'''or is not determined at \((\tau(a),\sigma(b))\) in the claimed way''')],
 invented="'Differs' is read for two determined answers that are unequal. The second disjunct is a contrast of determinacy: Ans_E(τ(a),σ(b)) = ⊥ while Ans_E(1,σ(b0)) ≠ ⊥, where (A) makes the target's answer at (a,b) ⊥ as well; 'in the claimed way' is read as the candidate's answer there being ⊥, as the target's is.",
 others=["a declared input saying in what way the answer is claimed to be undetermined (for example, which values remain)", "drop the clause: the contrast is 'differs' only"],
 core=["§6"]),

dict(id="I23", title="The first sentence of non-circular dependence, read as a heading gloss",
 quotes=[(255, r'''**Non-circular dependence.** The answer follows by evaluating \(E\) under its independent boundary conditions.''')],
 invented="The sentence adds no condition of its own: every answer in the formal core is computed by evaluating E at (τ(a),σ(b)), and σ(b) is fixed by b alone ('independent'). It is recorded as NC0 and is met by every candidate.",
 others=["a condition that E's boundary data carry nothing of the target's answer beyond σ(b) (formally automatic here, since σ is a function of b)", "a condition on how E's answer is computed (by propagation, not lookup), which would need a notion of computation the text does not give"],
 core=["§6"]),

dict(id="I24", title="NC1: the target's answer as an unanalysed boundary input or component, read structurally",
 quotes=[(255, r'''The target's answer does not appear, at the declared grain, as an unanalysed boundary input or as a component; moving an assertion from an input slot into a component named "law" does not discharge this. Identity of that assertion with the target's answer is structural at the declared grain, not the indiscriminate identification of all logically equivalent mathematical statements.''')],
 invented="NC1 fails when E has a single component k (or a boundary coordinate) such that, for every (a,b) in C, L_k(τ(a),σ(b)) (or the boundary value at σ(b)) is exactly the relation that fixes E's designated answer ports to the target's answer Ans_p(a,b) and constrains nothing else: an 'answer slot'. 'Structural at the grain' = equality of relations of one component of E as given, not equality up to logical equivalence of statements.",
 others=["(a) leave NC1 out: non-circular dependence is the final sentence (NC2) alone", "(b) any single component whose relation by itself fixes the answer (semantic entailment)", "(c) syntactic identity of written assertions (needs a syntax of relations that (O) does not give)"],
 core=["§6"]),

dict(id="I25", title="Non-circular dependence is the conjunction of its sentences",
 quotes=[(255, r'''There exist \((a,b)\in C\) and a nonempty block \(G\subseteq\Gamma\) such that''')],
 invented="NonCircular(ℰ) := NC0 ∧ NC1 ∧ NC2, where NC2 is the existential final sentence. The earlier sentences are conditions, not commentary on NC2.",
 others=["NC2 alone is the condition; the earlier sentences explain it", "NC1 alone is the condition; NC2 illustrates it"],
 core=["§6"]),

dict(id="I26", title="'Relabelings'",
 quotes=[(257, r'''A contract consisting only of relabelings, or excluding every change under which the active commitments could matter to \(\mathcal Q\), admits no candidate that meets non-circular dependence''')],
 invented="An edit a is a relabeling for p when, at every b with (a,b) in C, the target's answer is determined and equal to its answer at the baseline: Ans_p(a,b) = Ans_p(1,b0) ≠ ⊥.",
 others=["an edit that acts on D as an automorphism (renaming ports or values)", "an edit that changes no relation of D at all"],
 core=["§6"]),

dict(id="I27", title="The stated scope: a declared statement over pairs",
 quotes=[(257, r'''The contract \(C\) is a stated subset of the edits the target admits, and every edit the target admits that is excluded from \(C\) is excluded by a stated scope, not silently.''')],
 invented="A scope statement Σ is a declared input naming a set Excl(Σ) ⊆ A_D × B_D; the clause holds when (A_D × B_D) \\ C ⊆ Excl(Σ). Pairs, not edits, are what C excludes. Every a in A_D counts as an edit the target admits.",
 others=["edits rather than pairs: every a with no pair in C is named in Σ", "Σ as a yes/no flag ('the scope is stated')"],
 core=["§6"]),

dict(id="I28", title="The grain as a label on the organizations compared",
 quotes=[(255, r'''The target's answer does not appear, at the declared grain''')],
 invented="The grain ℓ is carried as an index on each organization (E at grain ℓ is a given organization); NC1 and ≡_ℓ are evaluated on the organizations as given at that index. No map between grains is defined.",
 others=["a grain as a quotient map from a finer organization to a coarser one (components of the coarse one as unions of fine ones)"],
 core=["§0", "§6", "§13"]),

dict(id="I29", title="The restriction operation (E restricted to W): deletion",
 quotes=[(287, r'''Fix \(\mathcal E\) and a declared restriction operation. For \(W\subseteq\Gamma\), let \(E|W\) retain the commitments in \(W\) with the named background fixed; the commitments of \(E|W\) are \(W\).''')],
 invented="E|W is E with every component of Γ \\ W deleted (full relation at every edit and boundary, as L103 gives for deletion), the background untouched, J_E and V_E unchanged; the transport is t with λ restricted to W; the commitments are W.",
 others=["remove Γ \\ W from J_E (their ports then free, or removed)", "some other declared operation: the text names the operation as declared, and it is not among the declared inputs of L522"],
 core=["§7"]),

dict(id="I30", title="The worked examples of routes are set systems",
 quotes=[(307, r'''**Redundant routes.** \(\Gamma=\{a,b\}\), \(\mathsf S=\{\{a\},\{b\},\{a,b\}\}\)''')],
 invented="The examples of L305–L313 are read as statements about families S ⊆ P(Γ), not about a particular question and candidate; where a test needs a candidate that realizes one, the realization is a further invention, recorded with the test.",
 others=["realize each example by a concrete target, question and candidate before reading it"],
 core=["§7"]),

dict(id="I31", title="The routes of the infinitary example",
 quotes=[(311, r'''every set of indices unbounded in \(\mathbb N\) determines \(x=0\); no minimal route, and no route of one commitment, exists.''')],
 invented="The routes are exactly the sets W whose index set {n : d_n ∈ W} is unbounded; a bounded set leaves x anywhere in [-1/max, 1/max] and is not a route; the empty set is not a route. (The question is read as 'is x determined to be 0?'.)",
 others=["the text does not say that bounded sets are not routes; another question (for example 'is |x| ≤ 1/N for a stated N?') gives another route family"],
 core=["§7"]),

dict(id="I32", title="A table of observed answers: its counterpart and its relation",
 quotes=[(269, r'''A **table of observed answers** has no component whose relation is replaced by an intervention; it fails (F1) under any contract containing one.''')],
 invented="The table is a candidate with one active component k whose counterpart is the whole of D (all of J_D, projected onto k's ports) and whose relation is the same under every edit: the relation D gives at the baseline. 'An intervention' is a setting edit (I04).",
 others=["the table's counterpart is only the subnetwork around the answer port", "a table keyed by edits (then it is the other kind L269 names, which encodes the response)"],
 core=["§6", "§17"]),

dict(id="I33", title="The offer of one candidate in place of another: a primitive",
 quotes=[(315, r'''Two explanatory candidates for one question \(p\) are **rivals** when one of them has been offered as an answer to \(p\) in place of the other''')],
 invented="Offered(ℰ, ℰ', p) is a primitive relation (a record of offers), not defined in the formal core; rivals are symmetric (either one offered in place of the other).",
 others=["offers as events in histories, read through the physical module", "offers as a declared input (L522 does not list them)"],
 core=["§8", "§18"]),

dict(id="I34", title="A claim χ as a set of allowed behaviours at a pair, and the premise that it speaks of the target",
 quotes=[(315, r'''A candidate **conflicts with** a claim \(\chi\) at an admitted pair of the target that its transport translates, in \(C\) or outside it, when \(\chi\) excludes what the candidate's organization and transport give there: its answer, or every relation of the target's components under which it could meet (F1), (F2) and (A) there.'''),
         (315, r'''Either way the argument needs the premise that \(\chi\) speaks of the target under that pair's edit.''')],
 invented="At each pair, χ is modelled as a set Allow_χ(a,b) of assignments R of relations to the target's components (the behaviours χ allows). 'χ excludes its answer' := every R whose query answer is Ans_E(τ(a),σ(b)) lies outside Allow_χ(a,b). 'χ excludes every relation under which it could meet' := every R with Meets_ab(ℰ,R) lies outside Allow_χ(a,b). The premise that χ speaks of the target under the pair's edit is a separate yes/no input Applies(χ,a,b).",
 others=["χ as a sentence of a language with its own semantics, related to behaviours by a declared reading", "χ as constraining answers only (then the second disjunct cannot be expressed)"],
 core=["§8"]),

dict(id="I35", title="Conflict given χ: no requirement that each candidate can meet under χ",
 quotes=[(315, r'''Two candidates that some relations of the target's components would let both meet (F1), (F2) and (A) at a pair, when \(\chi\) excludes every such relation, conflict there given \(\chi\)''')],
 invented="ConflictGiven_χ(ℰ,ℰ';a,b) := some R lets both meet at (a,b), and every such R lies outside Allow_χ(a,b). Nothing is required of what each can meet under χ alone.",
 others=["the second disjunct of plain conflict with R restricted to Allow_χ: each can meet under some allowed R, and no allowed R lets both"],
 core=["§8"]),

dict(id="I36", title="'Two of their active components with one counterpart'",
 quotes=[(315, r'''as none do when two of their active components with one counterpart have different relations there.''')],
 invented="k in Γ and k' in Γ' have one counterpart when λ(k) = λ'(k') as subnetworks, their port translations have the same image, and θ'^-1∘θ is a bijection V_k → V_k' with matching value maps; 'different relations there' means L_k'(τ'(a),σ'(b)) ≠ β_*(L_k(τ(a),σ(b))) under that bijection β.",
 others=["one counterpart = the same subnetwork, whatever the port translations (then the clause can fail: the translations can carry one projected relation to two different relations)"],
 core=["§8"]),

dict(id="I37", title="'Easy to vary' is relative to an assessor",
 quotes=[(317, r'''A candidate is **easy to vary**, in the sense used here, when it and a rival pose a problem of the second kind''')],
 invented="ETV_j(ℰ) := for some ℰ', Problem_j(ℰ,ℰ';p) holds and is of the second kind. It inherits the assessor from 'problem'. (What hard to vary covers is parked by decisions S33–S34; this formalization touches only the text's 'easy to vary' and adds nothing about it.)",
 others=["assessor-free: some rival conflicts with it only outside C, ruled out or not", "for some assessor"],
 core=["§10"]),

dict(id="I38", title="Claims, their denials, and 'inconsistent with its conclusion'",
 quotes=[(397, r'''An argument is usable by \(j\) when each of its steps is (K2), and it rules out a claim when the claim is inconsistent with its conclusion and the claim's denial is not among its premises (below).''')],
 invented="Claims are sentences of a first-order language with classical ¬ and ∧; 'inconsistent with' is classical inconsistency of {φ, conclusion}. Inference forms themselves are arbitrary (an admitted form need not be classically sound); only the ruling-out relation uses classical consistency.",
 others=["inconsistency relative to j's own admitted forms", "claims as sets of situations, inconsistency as disjointness"],
 core=["§9"]),

dict(id="I39", title="'Among its premises', read structurally; records made from a claim",
 quotes=[(397, r'''An argument does not rule out a claim when the claim's denial is among its premises, alone or joined to other claims by "and", read structurally as non-circular dependence reads identity (Part V) and not by logical equivalence alone; nor does an argument whose record leaf was made from a claim rule out that claim's denial.''')],
 invented="¬φ is among the premises when some leaf, flattened as a conjunction, has ¬φ as a conjunct, up to renaming of bound variables and the order of conjuncts. 'Made from a claim' is a primitive relation MadeFrom(leaf, ψ) on record leaves.",
 others=["up to a declared set of structural rewrites", "logical equivalence (the text excludes it)"],
 core=["§9"]),

dict(id="I40", title="Live through a step: a step below, and essential premises",
 quotes=[(387, r'''**Usability.** For argument step \(u\) with essential premises \(\operatorname{Prem}(u)\), the premises its inference form uses:'''),
         (393, r'''\(d\) is the conclusion of a step of the same argument as \(u\) that is usable by \(j\)''')],
 invented="An argument is a finite tree; Prem(u) is the set of u's children that its form uses. The step whose conclusion makes d live lies in the subtree below u, so Usable is defined by recursion on height and is well founded.",
 others=["any step of the argument, the definition read as a least fixed point", "arguments as finite acyclic graphs, one node shared by several steps"],
 core=["§9"]),

dict(id="I41", title="Tentative acceptance over time; withdrawal",
 quotes=[(393, r'''or a premise \(j\) tentatively accepts, having taken it up, for whatever reason, and not withdrawn it''')],
 invented="Accepted_j(ξ) is the set of claims j has taken up before ξ and not withdrawn before ξ; Live, Usable and ruled out are evaluated at a time ξ. Accepted_j is a declared input (L522).",
 others=["untimed sets (one assessor state)"],
 core=["§9"]),

dict(id="I42", title="Scope_j: within the declared contract, grain and boundary",
 quotes=[(393, r'''\(\operatorname{Scope}_j(u)\): \(u\) is applied within the contract, grain and boundary \(j\) has declared for it''')],
 invented="Each step u carries an index (C_u, ℓ_u, β_u); j declares (C_j(u), ℓ_j(u), β_j(u)); Scope_j(u) holds when C_u ⊆ C_j(u), ℓ_u = ℓ_j(u) and β_u = β_j(u).",
 others=["equality of contracts", "steps without an index, Scope_j vacuous for them"],
 core=["§9"]),

dict(id="I43", title="(K3): what it adds and what 'nothing narrower' says",
 quotes=[(395, r'''For \(T\land B\land I\Rightarrow O\), an argument usable by \(j\) that rules out \(O\) rules out \(T\land B\land I\) together for \(j\), and nothing narrower. (K3)''')],
 invented="(i) If j has a usable argument concluding ¬O, the conditional T∧B∧I ⇒ O is live for j and j admits modus tollens, the argument extended by one step rules out T∧B∧I for j. (ii) 'Nothing narrower': from those premises alone no argument rules out T, B or I by itself, since classically ¬O, T∧B∧I ⇒ O and T have a common model.",
 others=["(K3) as a restriction on j's admitted forms (j admits no form that concludes ¬T from them)", "(K3) as a definition of what a test rules out, not a consequence of (K2)"],
 core=["§9"]),

dict(id="I44", title="Causal precedence in a history is transitive",
 quotes=[(375, r'''A history \(h\) is a set of occurrences with an acyclic causal precedence \(\prec_h\) (write \(\preceq_h\) for its reflexive closure)''')],
 invented="≺_h is a strict partial order (irreflexive and transitive), so ⪯_h is a partial order.",
 others=["≺_h any acyclic relation and ⪯_h its reflexive closure only (then ⪯_h need not be transitive)", "⪯_h the reflexive-transitive closure of an acyclic ≺_h"],
 core=["§11"]),

dict(id="I45", title="'Event' is a set of occurrences",
 quotes=[(169, r'''An **occurrence** is a physically located carrier.'''),
         (161, r'''Its formulation is still an event.'''),
         (397, r'''A record leaf is a reference to an event with an interpreted claim.''')],
 invented="An event is a nonempty set of occurrences of a history; a record leaf refers to one; an assessment and a formulation are events. 'Event' adds no sort beyond occurrences.",
 others=["events as a separate primitive sort", "events as occurrences of edit–boundary pairs only"],
 core=["§11"]),

dict(id="I46", title="Active route: 'represented input', 'operative result', 'applicable relations', 'declared contrasts'",
 quotes=[(375, r'''An **active route** is a connected subnetwork of actual occurrences joining a represented input to an operative result, whose components meet the applicable relations and which has nonconstant dependence on the represented distinction under the declared contrasts.''')],
 invented="Given the organization Org_ℓ(h) that the physical module assigns to the history h: an active route for a result occurrence r is a set R of occurrences of h, connected by the instantiated connections, containing an input occurrence i whose port carries a represented distinction and the result occurrence r (the 'operative result' is a designated result occurrence); every occurrence of R lies on a ≺_h-chain from i to r inside R; each occurrence of R meets the relation Org_ℓ(h) gives it ('the applicable relations'); and for a declared set K of pairs of values of i's port, setting i's port to the two values of some pair in K gives different values at r in Org_ℓ(h).",
 others=["'operative result' = a result that later changes how the system proceeds (L73's operative return)", "dependence read on the actual history only, without setting i's port", "'connected' read without direction"],
 core=["§11"]),

dict(id="I47", title="Reason use: 'structural map', 'role bindings', 'the same transition', 'operative deliberative rule'",
 quotes=[(385, r'''**Reason use.** A response uses a reason when a structural map from the represented objection into the response suborganization preserves role bindings, sends content-preserving recodings to the same transition, sends content changes to the changes specified by the operative deliberative rule, and lands on an active route.''')],
 invented="The represented objection ob is a content with role bindings (a map from role names to its ports); a structural map m sends ob's ports to ports of the response suborganization R, preserving role names; Rec is a declared set of content-preserving recodings and Chg a declared set of content changes of ob; m(ρ·ob) induces the same state change of R as m(ob) for ρ in Rec; m(γ·ob) = Rule(γ)(m(ob)) for γ in Chg, with Rule a declared map ('the operative deliberative rule'); some image port of m lies on an active route (I46).",
 others=["the deliberative rule as a component of the system's organization, picked out by its signature", "the structural map as a transport (π,τ,σ,λ), making reason use a fidelity condition"],
 core=["§9"]),

dict(id="I48", title="Contents, 'c's contract', and transports into a content",
 quotes=[(169, r'''A **content** is an organization together with its contract-relative commitments.'''),
         (205, r'''faithful on \(c\)'s contract, whose provenance is selected or constructed'''),
         (413, r'''both faithful on \(c\)'s contract at grain \(\ell\).''')],
 invented="A content is c = (E_c, C_c, Γ_c) with C_c ⊆ A_Ec × B_Ec a contract on c's own organization (for the organization of a candidate for p: C_c := τ[C_p]). A transport t: X → E_c is faithful on c's contract when it meets (F1) and (F2) on the preimage {(a,b) ∈ A_X × B_X : (τ(a),σ(b)) ∈ C_c}, with Γ_c as the active components; a transport from c is faithful on C_c directly.",
 others=["a separately declared contract on the carrier's organization", "faithfulness on C_c read through a declared inverse of τ"],
 core=["§11", "§12", "§13"]),

dict(id="I49", title="'Faithful' and 'fidelity': the narrow extent by default, the wide one where a line asks for it",
 quotes=[(189, r'''A transport is **faithful on \(C\)** when it meets the component and global fidelity conditions of Part V.'''),
         (247, r'''**Question fidelity.**'''),
         (520, r'''Account, from fidelity under change, non-circular dependence and non-vacuity (E).'''),
         (630, r'''so the exchange carries the fidelity and the answers of \(t_1\) over to the second transport''')],
 invented="Faithful_C(t) := (F1) ∧ (F2) on C (the narrow extent L189 defines). Fid⁺_C(t) := (F1) ∧ (F2) ∧ (A) on C (the wide extent, used where a line names (A) as fidelity: L247's heading, L520). Each use of the word is assigned one extent in FC104.",
 others=["wide everywhere (then L630's 'the fidelity and the answers' says one thing twice)", "narrow everywhere (then L520 names no source for (A) and L247's heading is a name only)"],
 core=["§5", "§12"]),

dict(id="I50", title="A violation at a pair: which conditions fail",
 quotes=[(220, r'''- a **violation** occurs when fidelity fails at \((a,b)\);''')],
 invented="Violation(t;a,b) := not [(F1) at (a,b) and the valuation equation of (F2) at (a,b)] (narrow). Violation⁺ adds (A) at (a,b). Both are carried; FC20 asks when they coincide.",
 others=["only (A) at (a,b) (a failed prediction)", "the whole of (F2), homomorphism clause included"],
 core=["§12"]),

dict(id="I51", title="'Prediction' for a transport not said to reach the simulation layer",
 quotes=[(151, r'''A measure that identifies an outcome, together with a prediction of the outcome from it through a transport faithful on the contract, answers the identification question''')],
 invented="Pred_t(a,b) := Ans_E(τ(a),σ(b)) for any transport t: D → E, extending L219's definition, which is for transports to S.",
 others=["L151's 'prediction' in the everyday sense, not the defined term"],
 core=["§12"]),

dict(id="I52", title="Selection: the parameters witnessed in a physical history",
 quotes=[(195, r'''There is a population \(\mathcal T\) of candidate transports, a variation operator \(\mu\) on \(\mathcal T\), a finite history \(H\subseteq C\) of edit–boundary pairs actually encountered, and a survival condition requiring fidelity on \(H\).'''),
         (195, r'''No member of the history represents \(t\), \(H\), or the survival condition.''')],
 invented="μ: 𝒯 → P(𝒯); the survival condition is Faithful_H (narrow). Sel(t;𝒯,μ,H) also requires a physical selection history h_sel in which the pairs of H occur and the members of 𝒯 are admitted by the physics (L481), and in which no occurrence represents (R) t, H or the survival condition. 'Member of the history' is read as an occurrence of h_sel, since the members of H are pairs and cannot represent.",
 others=["a purely formal Sel with no physical witness (then 𝒯 = {t}, μ the identity and H = ∅ make every transport 'selected': FC77)", "H required to be nonempty"],
 core=["§12"]),

dict(id="I53", title="'Exactly one of three provenances': one whole history",
 quotes=[(193, r'''A transport \(t\) whose domain is an organization of a physical system has exactly one of three provenances, determined by its history in the physical module:'''),
         (201, r'''Neither provenance is reducible to the other: a selected transport has no represented target and no criticism in its history; a constructed one has both.''')],
 invented="Sel and Con are evaluated on one history: the whole physical history of t up to the attribution. Con then excludes Sel (Con puts a represented target in that history; Sel has none).",
 others=["Sel and Con evaluated on different parts of the history (then both can hold, as L201's 'Construction may operate on selected material' allows, and 'exactly one' needs a rule of precedence)"],
 core=["§12"]),

dict(id="I54", title="Inherited provenance: a rule of carrying over, per part",
 quotes=[(211, r'''A carrier keeps its provenance when present access to it is lost, and a later record made from the carrier carries that provenance, not a second, independent one.'''),
         (405, r'''A small binding newly prepared inside received content is construction of that binding, and the rest of the content keeps its inherited provenance.'''),
         (409, r'''Use does not by itself construct: received content used as it was received keeps its inherited provenance.''')],
 invented="Provenance is assigned to each part of a transport (each component with its counterpart binding). A content-preserving transfer (relay, record) from carrier o to carrier o' gives each part at o' the provenance it had at o; a binding newly built gets Con; 'inherited' is not a fourth value but the rule by which Sel, Con and Dec carry over.",
 others=["'inherited' as a fourth provenance value", "provenance per whole transport only (then L405's 'the rest of the content keeps' cannot be written)"],
 core=["§12"]),

dict(id="I55", title="Deploy: 'integrated into problem-directed activity', 'nontrivial use respect'",
 quotes=[(403, r'''integrated into problem-directed activity and serving the declared use task \(U\) as a retained capability (Part XII). The repertoire \(R_{\beta,\ell}(s,\xi)\) is the set of contents deployable in some nontrivial use respect.''')],
 invented="Deploy_βℓ(s,c,ξ;U) := for some occurrence o of s at ξ, Rep_ℓ(o,c), Integrated(o,s,ξ) and, for some χ, Can_Ωβ(ξ,U;χ) with a realization that uses o. Integrated and Nontrivial(U) are primitive predicates read through the physical module.",
 others=["Integrated defined through active routes (o lies on an active route to a problem's result)"],
 core=["§13"]),

dict(id="I56", title="Build: 'prepares', 'nontrivial binding construction', 'content-preserving transfer'",
 quotes=[(405, r'''**Construction.** \(\operatorname{Build}_{\beta,\ell}(s,c,h,e)\) is met when an actual subhistory owned by \(s\) and delimited at \(e\) prepares a represented organization for explanatory use of \(c\), contains a nontrivial binding construction relevant to that use, and is not a composition of content-preserving transfers.''')],
 invented="Build := for some subhistory h' of h ending at e and owned by s, Prepares(h',c), BindingConstruction(h',c) and not TransferComposite(h'), with the three as primitive predicates read through the physical module.",
 others=["Build defined through Con (a construction trace)", "BindingConstruction defined through reason use (L409)"],
 core=["§13"]),

dict(id="I57", title="Repair: how the aims are read at ξ and over [ξ, ξ']; which aim ProducedBy runs to",
 quotes=[(441, r'''In (P), accordingly, \(r(\xi')\) says of a protected condition \(r\) that it was met on every occasion it covers from \(\xi\) to \(\xi'\), not only at \(\xi'\).'''),
         (441, r'''\(\operatorname{ProducedBy}\) is met when an active route (Part IX) runs from \(\Delta\) to the repair''')],
 invented="An aim is (cond, Occ) with Occ a set of times. o(ξ) for o in O: cond met at ξ. On the left of (P), r(ξ) := cond met at ξ if ξ ∈ Occ_r, and holds otherwise; on the right, r(ξ') := cond met at every ω ∈ Occ_r with ξ ≤ ω ≤ ξ'. ProducedBy(Δ,ξ,ξ';O) := some o in O with ¬o(ξ) ∧ o(ξ') has an active route from an occurrence of Δ to the occurrence at which its cond comes to be met; it need not be the o of (P)'s first conjunct.",
 others=["tie ProducedBy to the same o as the first conjunct", "r(ξ) on the left also read over an interval"],
 core=["§14"]),

dict(id="I58", title="'Losses outside P': the aims considered, and 'exposed'",
 quotes=[(441, r'''Losses outside \(P\) must be exposed.''')],
 invented="A repair claim carries a declared set Aims* ⊇ O ∪ P of aims under consideration and an exposure record X; the claim is well formed when {r ∈ Aims* \\ P : r(ξ) ∧ ¬r(ξ')} ⊆ X. Aims* is a declared input that L522 does not list.",
 others=["all aims the system holds, read through the physical module", "exposure as a statement in the record, not a set"],
 core=["§14"]),

dict(id="I59", title="Explanatory aims: L443 read as a characterization of O_ex",
 quotes=[(443, r'''**Created explanation.** An explanatory aim requires a deployable account, or the correction of a use through one.''')],
 invented="O_ex ⊆ O is a declared marking of aims; L443 is read as: o is explanatory when its condition is 's possesses a deployable account of a stated question' or is L443's 'the correction of a use through' a deployable account. (EX) imposes the same conditions on both kinds.",
 others=["L443 as a necessary condition only", "O_ex defined by (EX)'s own conditions"],
 core=["§14"]),

dict(id="I60", title="ProducesVia: 'the relevant binding of c'",
 quotes=[(453, r'''\(\operatorname{ProducesVia}(\Delta,c,o;\xi,\xi')\) is met when an active route that runs from \(\Delta\) to the repair of \(o\) contains the relevant binding of \(c\).''')],
 invented="The relevant binding of c is the binding named in c's construction trace (Build's binding construction); 'contains' means some occurrence of the route instantiates it.",
 others=["any occurrence that carries c"],
 core=["§14"]),

dict(id="I61", title="Tasks and executions; 'complete' in F read as (CT1)'s completion",
 quotes=[(461, r'''a task a specified input-to-output attribute transformation with explicit resources and side effects.'''),
         (469, r'''Execution families are nonempty on admitted inputs; deadlock is not a vacuous performance of the task.'''),
         (471, r'''\(F(C)\) = states whose executions all complete and return into \(C\).''')],
 invented="A task T is a relation between inputs and outputs, with dom T and T[i]. Exec(π,z,i;χ) is a set of executions, each with a completion flag, an output o and a final constructor state z'. F(X) := {z : for every i in dom T and every η in Exec(π,z,i;χ), η completes with o in T[i] and z' in X}: 'complete' is read as (CT1)'s 'completes with o ∈ T[i]'. Nonemptiness of Exec (L469) is a standing assumption for z in C and i in dom T, not part of F.",
 others=["'complete' without the output condition (then C ⊆ F(C) is weaker than (CT1))", "nonemptiness inside F (F(X) then leaves out states with no executions)"],
 core=["§15"]),

dict(id="I62", title="Tolerances: stricter tolerances admit fewer tasks; Admit contains every realized task",
 quotes=[(479, r'''form a directed preorder \(Q_\Theta\), in which \(q\) precedes \(q'\) when \(q'\) admits no performance \(q\) excludes, and none of them is exact;'''),
         (479, r'''\(\mathsf{Admit}^{q,r}_\Theta\) is the set of tasks physically achievable at tolerances \((q,r)\);''')],
 invented="q precedes q' when q' excludes at least what q excludes (q' is at least as strict). Admit^{q,r} is antitone in (q,r). A task with a realization, owned or not, at (q,r) is in Admit^{q,r} (so (CT3) follows from the definitions).",
 others=["Admit given by the physical module with no stated link to realizations (then (CT3) is an assumption)"],
 core=["§15"]),

dict(id="I63", title="A tag such as (I2) names the sentence before it",
 quotes=[(329, r'''The feature is identified at \(y\) exactly when \(Z_y\neq\varnothing\land|f[Z_y]|=1\). (I1)'''),
         (335, r'''no allowed path joins states of different invariant value. (O1)'''),
         (471, r'''the greatest fixed point is the union of the sets \(D\) with \(D\subseteq F(D)\). (CT2)''')],
 invented="Each parenthesized tag names the sentence it follows, as it can only do at L395 and L471 (nothing follows the tag there). So (I1) is the definition of identification at y, (I2) the factorization claim, (I3) the kernel criterion, and (O1) the invariance claim.",
 others=["a tag names the sentence after it (then (I2) is the kernel criterion and (O1) is 'Equal values do not suffice for reachability')"],
 core=["§17"]),

dict(id="I64", title="Identification: 'attainable', and the admitted states in the linear case",
 quotes=[(329, r'''It is identified on every attainable \(y\) exactly when \(f=\bar f\circ g\) for some \(\bar f\).'''),
         (329, r'''For linear \(g\) and linear feature \(c^\top\), identification is \(\ker g\subseteq\ker c^\top\).''')],
 invented="y is attainable when y ∈ g[Z]. In the linear case Z is the whole space ℝ^n and 'identification' is identification at every attainable y.",
 others=["Z a proper subset (a cone or box of admitted states; then the kernel criterion can fail)", "identification at one given y"],
 core=["§17"]),

dict(id="I65", title="The pole and its shadow, encoded",
 quotes=[(325, r'''Stipulate \(H:=U_H,\ \theta:=U_\theta,\ L:=H\cot\theta\)'''),
         (325, r'''It is faithful under the identification contract, whose edits alter the observed \(L\).''')],
 invented="Ports H, θ, L; the exogenous values u_H, u_θ carried by the boundary b = (u_H, u_θ); components c_H (footprint {H}, relation H = u_H), c_θ (θ = u_θ), c_L (footprint {H, θ, L}, relation L = H cot θ); edits: set H to h, set θ to φ, set L to l, each replacing its component (I04), and their composites. For tests, finite grids (H in {1,2,3}, θ in {30°,45°,60°}). The production question: Q reads L. The identification contract: boundaries varying u_H so that different values of L are observed, and Q returning the fibre {H : H cot θ = observed L}; 'edits that alter the observed L' are read as these boundary changes.",
 others=["u_H and u_θ as ports", "the identification contract with edits to a measuring component that reads L", "real values handled symbolically"],
 core=["§17"]),

dict(id="I66", title="The odd-order skew-symmetric case, encoded",
 quotes=[(343, r'''Contract: remove skewness; remove oddness; remove both; field arithmetic and determinant–invertibility held fixed.''')],
 invented="Ports: the order n, the matrix entries, det, inv; components: skew (Mᵀ = −M), odd (n odd), determinant (Leibniz sum), invertibility (inv ⟺ det ≠ 0); edits: delete skew, delete odd, delete both; Q: 'does the family contain an invertible matrix?'. For tests: n in {1,2,3}, entries in GF(p) for an odd prime p (the statement also holds there, since 2 is invertible) or small integer ranges with exact determinants. The Leibniz candidate: one component per permutation term and a sum component.",
 others=["real entries handled symbolically", "entries in GF(2), where the statement fails (a different field arithmetic, which the contract holds fixed)"],
 core=["§17"]),

dict(id="I67", title="A contract as an organization (Argument 5), encoded",
 quotes=[(590, r'''Give it ports (the edits and their boundaries), components (the closure conditions, each with the relation it imposes on its ports, as (O) requires), and admitted edits (add or remove a change; alter \(\mathcal Q\)).''')],
 invented="One port m_(a,b) with domain {0,1} for each (a,b) in A × B (membership in C) and one port q whose domain is a declared set of queries; components: the baseline condition (m_(1,b0) = 1) and whatever closure conditions the question declares (for example m_(a1,b) ∧ m_(a2,b) → m_(a2·a1,b)); edits: set a membership port, set q, and composites.",
 others=["ports for edits only, boundaries fixed", "no closure conditions beyond the baseline (the text names 'the closure conditions' without saying which)"],
 core=["§17"]),

dict(id="I68", title="Argument 10's two-layer episode, encoded; 'recent occupancy'",
 quotes=[(620, r'''Stipulate an object layer \(P\): a line of cells; two things, each with a position and a velocity; continuity components; admitted edits: displace a thing, set its velocity, occlude a cell, swap the two identities.'''),
         (622, r'''\(S_0\) predicts occupancy from recent occupancy.''')],
 invented="A line of N cells (N = 6 for tests), two things with position in {0..N−1} and velocity in {−1,0,1}, time steps 0..K; continuity: pos(t+1) = pos(t) + vel(t), with a stated rule at the ends (reflection); occluding cell c makes the occupancy reading of c empty; swap exchanges the two things' positions and velocities. S0 predicts occupancy at t+1 from the occupancy of the last w steps, with the window w shorter than the occlusion.",
 others=["continuous positions", "an unbounded window (then an occupancy predictor could extrapolate through an occlusion, and the 'structural' failure can fail: FC102)", "stopping at the ends instead of reflecting"],
 core=["§17"]),

dict(id="I69", title="'Built alike': the exchange is an automorphism",
 quotes=[(630, r'''The two things are built alike in \(P\), and their persistence components alike in \(S_1\)''')],
 invented="The exchange ψ of the two things is a bijection of P's ports, components, edits and boundaries that preserves L, maps C onto C and leaves the query's answers unchanged; the same holds in S1 for the exchange of the persistence components.",
 others=["an isomorphism between the two things' subnetworks only"],
 core=["§17"]),

dict(id="I70", title="A structure-preserving bijection of all the data (Argument 8)",
 quotes=[(612, r'''Transporting all carriers, relations, transports, histories, contracts and declared inputs along structure-preserving bijections preserves (E), (G), (P), (EX).''')],
 invented="Bijections of ports, values, components, edits (a partial-monoid isomorphism), boundaries and occurrences (preserving ≺_h and the physical module's interpretation), with the query, its designation and every declared input carried along (Q^φ(φ·O, φa, φb) = Q(O,a,b)).",
 others=["the physical module not transported (then (G) and (EX) need it to commute with the bijection)"],
 core=["§18"]),

dict(id="I71", title="The 'value' of a transport at a pair (Argument 3)",
 quotes=[(572, r'''at which some \(t'\in\mathcal T\), also surviving on \(H\), has a different value from \(t\)''')],
 invented="value_t(a,b) := (τ(a), σ(b), (L^E_k(τ(a),σ(b)))_{k in J_E}): the translated pair and the relations the transport's organization has there. Members of 𝒯 share the codomain's ports and components and differ in relations; Argument 3's 'L_j(a,b) altered' is read as L^E_j(τ(a),σ(b)) altered.",
 others=["the prediction Ans_E(τ(a),σ(b)) only", "the π-image of Sol_D(a,b)"],
 core=["§12"]),

dict(id="I72", title="Respects as sufficient conditions; 'upstream'",
 quotes=[(151, r'''A production question has a \(\mathcal Q\) that reads an output port and a \(C\) containing interventions on upstream ports.''')],
 invented="The three sentences are sufficient conditions naming a respect, not definitions: production when Q reads an output port w and C contains a setting edit of a port upstream of w (v upstream of w: a chain of components, each reading the output of the one before, from v to w); identification when Q computes a fibre g^-1(y) and C contains edits to the observed value; obstruction when Y_p = {reachable, unreachable}. The respects need not exclude one another.",
 others=["necessary conditions (every production question has such Q and C)", "a function from (type of Q, shape of C) to one respect"],
 core=["§3"]),

dict(id="I73", title="'An answer to one is not an answer to the other': the narrow reading",
 quotes=[(151, r'''Two questions with the same \(D\) and different \((C,\mathcal Q)\) are different questions, and an answer to one is not an answer to the other.''')],
 invented="Narrow reading: meeting (E) on one does not by itself give (E) on the other. The wide reading (no candidate meets (E) on both) is carried as a claim to test (FC34).",
 others=["the wide reading", "'answer' as the answer profile Ans_p (different profiles)"],
 core=["§3"]),

dict(id="I74", title="Recursive capacity: target chains and enabling continuations",
 quotes=[(492, r'''\forall n<\omega\ \forall\text{ admitted target chains of length }n,\ \exists\text{ an owned enabling continuation}.''')],
 invented="A target chain of length n is a sequence d1, …, dn of aspects of the system's practice, each d(i+1) a description of di made a represented target, each step admitted by the physical module; an owned enabling continuation is an owned continuation in which dn becomes a represented target, criticism is directed at it and the result can change its operative use (L487).",
 others=["chains of scrutiny of one aspect repeated n times"],
 core=["§16"]),

dict(id="I75", title="The explanatory contents 𝔈_Θ",
 quotes=[(497, r'''With \(\mathfrak E_\Theta\) the explanatory contents that some carrier can hold under the physical module''')],
 invented="𝔈_Θ := {c : for some p, t, Γ, Account((c,p,t,Γ)), and the physical module admits some carrier instantiating c}. It is taken to be infinite where FC94 needs it.",
 others=["contents that some carrier holds at present"],
 core=["§16"]),

dict(id="I76", title="The three defects of a question, formally",
 quotes=[(161, r'''A question may fail to pick out its alleged target, assume an incompatible baseline, or combine incompatible requirements.''')],
 invented="A question is taken with a description Desc it answers to. 'Fails to pick out its alleged target': no organization satisfies Desc, or several do. 'Incompatible baseline': Sol_D(1,b0) = ∅, or b0 ∉ B. 'Incompatible requirements': the conditions Desc places on (C, Q) have no joint instance.",
 others=["the question as the tuple p alone (then the first defect cannot be written, since D is given in p)"],
 core=["§3"]),
]
